/// <summary>
/// Phase 2: per-SO pick list posting, then (on the End task) CSD wave/cleanup/export.
/// Always spawned by METSalesPickingListReservationBatch, never shown interactively.
/// </summary>
class METSalesPickingListFulfillmentBatch extends METRunBaseBatchMultiThreadBase
{
    SalesId                     salesId, csdSalesId;
    utcdatetime                 csdOrderExtractDateTime;
    RefRecId                    csdSalesOrderCount;
    boolean                     continueFromStagingLane;
    str                         csdGuid;
    container                   csdSalesOrderList;
    METSalesOrderExtractionId   extractionId;
    container                   shipmentIdList;
    SalesTable                  salesTable;
    METSalesTable               metSalesTable;
    WMSPickingRoute             wmsPickingRoute;
    InventParameters            inventParameter;
    InventLocation              inventLocation;
    int                         batchTransactionCommit;
    Map                         reservedQtyInSalesUnitMap = new Map(Types::Int64, Types::Real);
    Map                         reservedQtyInInventUnitMap = new Map(Types::Int64, Types::Real);
    str                         actionToPerform;
    boolean                     isError;
    boolean                     processExtraction;
    SalesUpdateRemain           salesUpdateRemainInstance;
    LineNum                     currentLineNum;
    ItemId                      currentItemId;
    METProcMetrics              procMetrics;
    str                         capturedErrorReason;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        salesId,
        csdSalesId,
        csdOrderExtractDateTime,
        csdSalesOrderCount,
        continueFromStagingLane,
        csdGuid,
        csdSalesOrderList,
        extractionId,
        shipmentIdList
    #endmacro

}

