/// <summary>
/// Gets/sets the SO this task processes.
/// </summary>
/// <param name = "_salesId">Sales order to process</param>
/// <returns>The current SalesId</returns>
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>
/// Gets/sets the CSD SalesId used for wave/print-mode checks.
/// </summary>
/// <param name = "_csdSalesId">CSD sales order id</param>
/// <returns>The current CSD SalesId</returns>
public SalesId parmCSDSalesId(SalesId _csdSalesId = csdSalesId)
{
    csdSalesId = _csdSalesId;
    return csdSalesId;
}

/// <summary>
/// Gets/sets the CSD extract datetime, used for the wave lookup on the End task.
/// </summary>
/// <param name = "_csdOrderExtractDateTime">CSD extract datetime</param>
/// <returns>The current value</returns>
public utcdatetime parmCSDSalesOrderExtractDateTime(utcdatetime _csdOrderExtractDateTime = csdOrderExtractDateTime)
{
    csdOrderExtractDateTime = _csdOrderExtractDateTime;
    return csdOrderExtractDateTime;
}

/// <summary>
/// Gets/sets the CSD order count passed to wave creation.
/// </summary>
/// <param name = "_csdSalesOrderCount">CSD order count</param>
/// <returns>The current value</returns>
public RefRecId parmCSDSalesOrderCount(RefRecId _csdSalesOrderCount = csdSalesOrderCount)
{
    csdSalesOrderCount = _csdSalesOrderCount;
    return csdSalesOrderCount;
}

/// <summary>
/// Gets/sets the staging-lane continuation flag.
/// </summary>
/// <param name = "_continueFromStagingLane">Staging-lane continuation flag</param>
/// <returns>The current value</returns>
public boolean parmContinueFromStagingLane(boolean _continueFromStagingLane = continueFromStagingLane)
{
    continueFromStagingLane = _continueFromStagingLane;
    return continueFromStagingLane;
}

/// <summary>
/// Gets/sets the CSD wave GUID.
/// </summary>
/// <param name = "_csdGuid">CSD wave GUID</param>
